const TEAMS=['Alfa','Bravo','Charlie','Delta','Echo','Foxtrot','Golf','Hotel','India','Juliett'];
const COLORS=['#ad413b','#284f85','#ba8930','#245f50','#775391','#b36332','#46703b','#456778','#a1446b','#313d66'];
const SYMBOLS=['<path d="M16 35 30 12 44 35h-8l-6-11-6 11z"/>','<path d="m32 9-15 20h11l-3 15 18-23H31z"/>','<path d="m15 18 9 7 6-13 6 13 9-7-4 20H19z"/>','<path d="m12 36 18-25 18 25zm12-6h12l-6-9z" fill-rule="evenodd"/>','<path d="M18 13h26v6H25v5h15v6H25v6h19v6H18z"/>','<path d="m13 13 17 9 17-9-6 24-11 8-11-8zm9 13 4 4 2-3zm10 1 2 3 4-4z"/>','<path d="M30 10c-21 11-20 25-3 26v9h6V36c17-1 18-15-3-26z"/>','<path d="M17 14h7v11h12V14h7v29h-7V32H24v11h-7z"/>','<path d="m30 10 17 18-17 18-17-18zm0 10-8 8 8 8 8-8z" fill-rule="evenodd"/>','<path d="M19 12h24v7h-6v18c0 13-23 13-23-1h8c0 5 7 5 7 0V19H19z"/>'];
function crest(name){const i=TEAMS.indexOf(name);return `<svg class="crest" viewBox="0 0 60 66" aria-hidden="true"><path fill="${COLORS[i]}" d="M4 3h52v35c0 13-15 21-26 26C19 59 4 51 4 38z"/><path fill="none" stroke="#ffffff66" stroke-width="2" d="M9 8h42v29c0 10-11 17-21 22C20 54 9 47 9 37z"/><g fill="#fff8df">${SYMBOLS[i]}</g></svg>`}
const KEY='touchline-league-v1';let matches=structuredClone(INITIAL_MATCHES);let storageOK=true;
function validScore(v){return v===null||(Number.isInteger(v)&&v>=0&&v<=99)}
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&saved.length===90&&saved.every((m,i)=>m.id===i&&m.home===INITIAL_MATCHES[i].home&&m.away===INITIAL_MATCHES[i].away&&validScore(m.hs)&&validScore(m.as_)&&['live','finished','upcoming'].includes(m.status)))matches=saved;}catch(e){storageOK=false}
function calculate(list){const rows=TEAMS.map((name,i)=>({name,i,p:0,w:0,d:0,l:0,gf:0,ga:0,gd:0,pts:0}));for(const m of list){if(m.status==='upcoming'||m.hs===null||m.as_===null)continue;const h=rows[TEAMS.indexOf(m.home)],a=rows[TEAMS.indexOf(m.away)];h.p++;a.p++;h.gf+=m.hs;h.ga+=m.as_;a.gf+=m.as_;a.ga+=m.hs;if(m.hs>m.as_){h.w++;a.l++;h.pts+=3}else if(m.hs<m.as_){a.w++;h.l++;a.pts+=3}else{h.d++;a.d++;h.pts++;a.pts++}}for(const r of rows)r.gd=r.gf-r.ga;return rows.sort((a,b)=>b.pts-a.pts||b.gd-a.gd||a.i-b.i)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(matches));storageOK=true}catch(e){storageOK=false}document.querySelector('#save-state').textContent=storageOK?'Saved on this browser':'Browser storage unavailable · changes last for this session'}
function renderTable(){document.querySelector('#standings').innerHTML=calculate(matches).map((r,i)=>`<tr><td>${i+1}</td><td><span class="team-label">${crest(r.name)}${r.name}</span></td><td>${r.p}</td><td>${r.w}</td><td>${r.d}</td><td>${r.l}</td><td>${r.gf}–${r.ga}</td><td>${r.gd>0?'+':''}${r.gd}</td><td>${r.pts}</td></tr>`).join('');const live=matches.filter(m=>m.status==='live').length;const el=document.querySelector('#live-indicator');el.textContent=live?`${live} match${live===1?'':'es'} live`:'No matches live';el.classList.toggle('is-live',live>0);document.querySelector('#progress').textContent=`${matches.filter(m=>m.status==='finished').length} / 90 finished`;document.querySelector('#upcoming').innerHTML=matches.filter(m=>m.status==='upcoming').slice(0,3).map(m=>`<div class="fixture">${crest(m.home)}${m.home}<span class="vs">v</span>${crest(m.away)}${m.away}<small>MD ${m.round}</small></div>`).join('')||'<p class="edit-hint">All fixtures are underway or complete.</p>'}
function renderMatches(){const round=Number(document.querySelector('#round').value);document.querySelector('#matches').innerHTML=matches.filter(m=>m.round===round).map(m=>`<article class="match ${m.status}" data-id="${m.id}"><div class="match-top"><span>MATCHDAY ${m.round} · DATE TBC</span><select aria-label="${m.home} versus ${m.away} status" data-field="status">${['upcoming','live','finished'].map(s=>`<option value="${s}" ${m.status===s?'selected':''}>${s==='live'?'● Live':s==='finished'?'Finished':'Upcoming'}</option>`).join('')}</select></div>${[['home','hs'],['away','as_']].map(([team,field])=>`<label class="score-row">${crest(m[team])}<span>${m[team]}</span><input type="number" inputmode="numeric" min="0" max="99" step="1" aria-label="${m.home} versus ${m.away}: ${m[team]} score" data-field="${field}" value="${m[field]??''}" placeholder="–"></label>`).join('')}</article>`).join('')}
function update(id,field,value){const m=matches.find(m=>m.id===id);if(!m)throw Error('Unknown match');if(field==='status'){if(!['live','finished','upcoming'].includes(value))throw Error('Invalid status');m.status=value;if(value!=='upcoming'){m.hs??=0;m.as_??=0}}else{if(!['hs','as_'].includes(field)||!validScore(value))throw Error('Scores must be whole numbers from 0 to 99');m[field]=value}save();renderTable()}
document.querySelector('#round').innerHTML=Array.from({length:18},(_,i)=>`<option value="${i+1}">Matchday ${i+1}</option>`).join('');
document.querySelector('#round').addEventListener('change',renderMatches);
document.querySelector('#matches').addEventListener('input',e=>{if(e.target.tagName!=='INPUT')return;const el=e.target;if(!el.validity.valid)return;update(Number(el.closest('[data-id]').dataset.id),el.dataset.field,el.value===''?null:Number(el.value))});
document.querySelector('#matches').addEventListener('change',e=>{if(e.target.tagName!=='SELECT')return;update(Number(e.target.closest('[data-id]').dataset.id),'status',e.target.value);renderMatches()});
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-current',t===b?'page':'false')});document.body.classList.toggle('matches-view',b.dataset.tab==='matches')}));
renderTable();renderMatches();if(!storageOK)document.querySelector('#save-state').textContent='Browser storage unavailable · changes last for this session';
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_league_standings',description:'Read the current local league standings.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({standings:calculate(matches)})})).catch(()=>{})}catch(e){}}
